    "LA_OU_TT_COMMENCE_TEXT" => array(
        "fr" => "deux jeunes hommes ambitieux et motivés ont décidé de créer leur propre opportunité, au lieu de la chercher ailleurs. ingénieur informatique option miage, hamid kennou et zakaria el haboussi, ont décidé de créer leur propre projet, partager la même vision et l'a concrétiser à travers leur façon de faire",
        "en" => "It all started in 2012, when two ambitious and motivated young men decided to create their own opportunity, instead of looking elsewhere. IT engineers, Hamid Kennou and Zakaria El haboussi, decided to create their own project, share the same vision and make it happen their own way.",
        "ar" => "قرر شابان طموحان ومتحمسان خلق فرصتهما الخاصة، بدلاً من البحث عنها في مكان آخر. مهندسا معلوماتية، حميد كنو وزكرياء الحبوصي، قررا إنشاء مشروعهما الخاص، تقاسم نفس الرؤية وتحقيقها من خلال أسلوبهما الخاص"
    ),

    "GES" => array(
        "fr" => "Global Entrepreneurship Summit",
        "en" => "Global Entrepreneurship Summit",
        "ar" => "القمة العالمية لريادة الأعمال"
    ),

    "GES_TEXT" => array(
        "fr" => "Hello World Agency a participé dans à la 5ème édition du Global Entrepreneurship Summit organisé à Marrekch en 2014, traitant l’utilisation des nouvelles  technologies et les effets exponentiels de l’innovation. « Les petites entreprises financent les grandes entreprises », une idée originale présentée et défendue par Hello World durant cette manifestation de caractère international",
        "en" => "Hello World Agency participated in the 5th edition of the Global Entrepreneurship Summit held in Marrekch in 2014, dealing with the use of new technologies and the exponential effects of innovation. \"Small companies finance big companies\", an original idea presented and defended by Hello World during this international event.",
        "ar" => "شاركت وكالة هيلو وورلد في النسخة الخامسة من القمة العالمية لريادة الأعمال المنظمة في مراكش سنة 2014، والتي تناولت استخدام التقنيات الجديدة والآثار المتسارعة للابتكار. «الشركات الصغيرة تموّل الشركات الكبيرة»، فكرة أصلية قدمتها ودافعت عنها هيلو وورلد خلال هذا الحدث ذي الطابع الدولي"
    ),

