    "APPARITION_TV_TEXT" => array(
        "fr" => "Distinguée par sa croissance économique exponentielle, Hello World avait l’opportunité de plusieurs passages télévisés sur des chaines reconnues comme AL Houra TV, 2M TV ainsi que des passages radios sur RTM, sans oublié ses apparitions sur la presse écrite « Celebrity »",
