        "ar" => "تميزت هيلو وورلد بنموها الاقتصادي المتسارع، فأتيحت لها فرصة العديد من الظهورات التلفزيونية على قنوات معروفة مثل الحرة تيفي و2M، بالإضافة إلى ظهورات إذاعية على RTM، دون أن ننسى حضورها في الصحافة المكتوبة «سيليبريتي»"
