        "ar" => "سياق السوق"
    ),

    "IA_INTRO_TITLE" => array(
        "fr" => "Introduction<br><em>Contextuelle</em>",
        "en" => "Contextual<br><em>Introduction</em>",
        "ar" => "مقدمة<br><em>سياقية</em>"
    ),

    "IA_INTRO_P1" => array(
        "fr" => "La digitalisation des entreprises au Maroc a franchi un cap décisif depuis 2020. Face à une pression croissante sur les coûts opérationnels et à l'exigence d'une réactivité continue (24/7), les approches traditionnelles montrent leurs limites. Les agents IA se positionnent aujourd'hui comme le levier de compétitivité incontournable pour les directions générales et directions des systèmes d'information cherchant à optimiser leur rentabilité.",
        "en" => "The digitalization of businesses in Morocco has crossed a decisive threshold since 2020. Faced with growing pressure on operating costs and the demand for continuous (24/7) responsiveness, traditional approaches are showing their limits. AI agents are now positioning themselves as the essential competitive lever for executive teams and IT leadership seeking to optimize profitability.",
        "ar" => "قطعت رقمنة الشركات في المغرب منعطفاً حاسماً منذ 2020. في مواجهة ضغط متزايد على التكاليف التشغيلية ومتطلبات استجابة مستمرة على مدار الساعة، تُظهر المقاربات التقليدية حدودها. تتموقع وكلاء الذكاء الاصطناعي اليوم كرافعة تنافسية لا غنى عنها للإدارات العامة وإدارات نظم المعلومات الساعية إلى تحسين ربحيتها."
    ),

    "IA_INTRO_P2" => array(
        "fr" => "Sur un marché marocain où des canaux comme WhatsApp et Telegram ont atteint une maturité exceptionnelle dans les échanges B2B et B2C, l'intégration de solutions conversationnelles intelligentes n'est plus une option. Hello World conçoit et déploie des systèmes autonomes capables de traiter vos flux documentaires, d'engager vos prospects et de fiabiliser votre service client en temps réel.",
        "en" => "In a Moroccan market where channels like WhatsApp and Telegram have reached exceptional maturity in B2B and B2C exchanges, integrating intelligent conversational solutions is no longer optional. Hello World designs and deploys autonomous systems capable of processing your document flows, engaging your prospects and making your customer service more reliable in real time.",
        "ar" => "في سوق مغربي بلغت فيه قنوات مثل واتساب وتيليغرام مستوى نضج استثنائي في التبادلات بين الشركات والأفراد، لم يعد دمج الحلول الحوارية الذكية خياراً. تصمم Hello World وتنشر أنظمة مستقلة قادرة على معالجة تدفقاتكم الوثائقية، والتفاعل مع عملائكم المحتملين، وتعزيز موثوقية خدمة عملائكم في الوقت الفعلي."
    ),

    "IA_INTRO_P3" => array(
        "fr" => "Nos offres sont taillées pour répondre aux exigences de conformité et de performance des grands comptes, des institutions semi-publiques et des appels d'offres stratégiques. Le retour sur investissement (ROI) de nos solutions s'observe dès les premiers mois de déploiement grâce à une automatisation maîtrisée et parfaitement intégrée à votre écosystème existant.",
        "en" => "Our offerings are tailored to meet the compliance and performance requirements of major accounts, semi-public institutions and strategic tenders. The return on investment (ROI) of our solutions is visible within the first months of deployment, thanks to controlled automation that's perfectly integrated with your existing ecosystem.",
        "ar" => "صُممت عروضنا لتلبية متطلبات الامتثال والأداء لدى الشركات الكبرى والمؤسسات شبه العمومية وطلبات العروض الاستراتيجية. يُلاحَظ العائد على الاستثمار (ROI) لحلولنا منذ الأشهر الأولى للنشر بفضل أتمتة محكمة ومدمجة بشكل مثالي في منظومتكم الحالية."
    ),

