    "SVC_PACK_PARAG_38" => array(
        "fr" => "<p>Des sites web haute performance et \"mobile-first\", conçus sur-mesure pour répondre aux besoins de votre entreprise. Tous les tarifs sont indiqués à titre indicatif (à partir de) et peuvent varier en fonction de vos demandes spécifiques.</p>",
        "en" => "<p>High-performing, \"mobile-first\" websites, custom-built to meet your business needs. All prices are indicative (starting at) and may vary depending on your specific requirements.</p>",
        "ar" => "<p>مواقع ويب عالية الأداء و\"الموبايل أولاً\"، مصممة خصيصاً لتلبية احتياجات شركتكم. جميع الأسعار المذكورة إرشادية (ابتداءً من) وقد تختلف حسب طلباتكم الخاصة.</p>"
    ),

    "SVC_PACK_PARAG_40" => array(
        "fr" => "<p>Gravissez les échelons des résultats Google et captez un trafic organique qualifié. Tous nos tarifs sont des prix de départ, basés sur des forfaits mensuels.</p>",
        "en" => "<p>Climb the ranks of Google results and capture qualified organic traffic. All our prices are starting prices, based on monthly packages.</p>",
        "ar" => "<p>ارتقوا في نتائج جوجل واجذبوا زيارات عضوية مؤهلة. جميع أسعارنا هي أسعار انطلاق، مبنية على باقات شهرية.</p>"
    ),

    "SVC_PACK_PARAG_46" => array(
        "fr" => "<p>Développez votre communauté et boostez la notoriété de votre marque là où se trouvent vos clients. Les tarifs indiqués sont des prix de base. Tous nos packs nécessitent un budget publicitaire minimum.</p>
            <p><i class=\"fas fa-exclamation-triangle\"></i> <strong>Note</strong> : Si les packs de gestion des réseaux sociaux nécessitent des services de design additionnels (branding, graphismes complexes, etc.), des frais supplémentaires pourront être appliqués.</p>",
        "en" => "<p>Grow your community and boost your brand awareness wherever your customers are. Prices shown are base prices. All our packages require a minimum advertising budget.</p>
            <p><i class=\"fas fa-exclamation-triangle\"></i> <strong>Note</strong>: If the social media management packages require additional design services (branding, complex graphics, etc.), extra fees may apply.</p>",
        "ar" => "<p>طوروا مجتمعكم وعزّزوا شهرة علامتكم التجارية أينما كان عملاؤكم. الأسعار المذكورة هي أسعار أساسية. تتطلب جميع باقاتنا ميزانية إعلانية دنيا.</p>
            <p><i class=\"fas fa-exclamation-triangle\"></i> <strong>ملاحظة</strong> : إذا تطلبت باقات إدارة شبكات التواصل الاجتماعي خدمات تصميم إضافية (هوية بصرية، رسوم معقدة، إلخ)، فقد تُطبَّق رسوم إضافية.</p>"
    ),

    "SVC_PACK_NOTE_38" => array(
        "fr" => "<b>Les Packs 1 & 2</b> bénéficient d'une tarification préférentielle spécifiquement conçue pour soutenir l'écosystème entrepreneurial marocain. Ils sont donc strictement réservés aux entreprises au cours de leurs 24 premiers mois d'activité. Tous les prix indiqués sont des tarifs de base. Le prix final peut varier en fonction des demandes spécifiques, des intégrations personnalisées, des besoins de conception supplémentaires (graphisme, identité visuelle, etc.) ou de l'élargissement de la portée du projet.",
        "en" => "<b>Packages 1 & 2</b> benefit from preferential pricing specifically designed to support the Moroccan entrepreneurial ecosystem. They are therefore strictly reserved for businesses within their first 24 months of activity. All prices shown are base rates. The final price may vary depending on specific requests, custom integrations, additional design needs (graphics, visual identity, etc.) or an expanded project scope.",
        "ar" => "تستفيد <b>الباقتان 1 و2</b> من تسعير تفضيلي مصمم خصيصاً لدعم المنظومة الريادية المغربية. لذا فهما مخصصتان حصرياً للشركات خلال أول 24 شهراً من نشاطها. جميع الأسعار المذكورة هي أسعار أساسية. قد يختلف السعر النهائي حسب الطلبات الخاصة، التكاملات المخصصة، احتياجات التصميم الإضافية (رسوم، هوية بصرية، إلخ) أو توسيع نطاق المشروع."
    ),

    "SVC_PACK_NOTE_40" => array(
        "fr" => "Pour<b> « Le Pilote SEO »</b> bénéficie d'une tarification préférentielle spécifiquement conçue pour soutenir l'écosystème entrepreneurial marocain et est donc strictement réservé aux entreprises au cours de leurs 24 premiers mois d'activité. Tous les prix indiqués sont des tarifs de base. Le prix final peut varier en fonction des demandes spécifiques, des intégrations personnalisées, des besoins de conception supplémentaires (graphisme, identité visuelle, etc.) ou de l'élargissement de la portée du projet.",
        "en" => "The<b> \"SEO Pilot\"</b> package benefits from preferential pricing specifically designed to support the Moroccan entrepreneurial ecosystem and is therefore strictly reserved for businesses within their first 24 months of activity. All prices shown are base rates. The final price may vary depending on specific requests, custom integrations, additional design needs (graphics, visual identity, etc.) or an expanded project scope.",
        "ar" => "تستفيد باقة <b>«التجربة SEO»</b> من تسعير تفضيلي مصمم خصيصاً لدعم المنظومة الريادية المغربية، لذا فهي مخصصة حصرياً للشركات خلال أول 24 شهراً من نشاطها. جميع الأسعار المذكورة هي أسعار أساسية. قد يختلف السعر النهائي حسب الطلبات الخاصة، التكاملات المخصصة، احتياجات التصميم الإضافية (رسوم، هوية بصرية، إلخ) أو توسيع نطاق المشروع."
    ),

    "SVC_PACK_NOTE_DEFAULT" => array(
        "fr" => "<b>Les Packs 1</b> bénéficie d'une tarification préférentielle spécifiquement conçue pour soutenir l'écosystème entrepreneurial marocain. Ils sont donc strictement réservés aux entreprises au cours de leurs 24 premiers mois d'activité. Tous les prix indiqués sont des tarifs de base. Le prix final peut varier en fonction des demandes spécifiques, des intégrations personnalisées, des besoins de conception supplémentaires (graphisme, identité visuelle, etc.) ou de l'élargissement de la portée du projet.",
        "en" => "<b>Package 1</b> benefits from preferential pricing specifically designed to support the Moroccan entrepreneurial ecosystem. It is therefore strictly reserved for businesses within their first 24 months of activity. All prices shown are base rates. The final price may vary depending on specific requests, custom integrations, additional design needs (graphics, visual identity, etc.) or an expanded project scope.",
        "ar" => "تستفيد <b>الباقة 1</b> من تسعير تفضيلي مصمم خصيصاً لدعم المنظومة الريادية المغربية. لذا فهي مخصصة حصرياً للشركات خلال أول 24 شهراً من نشاطها. جميع الأسعار المذكورة هي أسعار أساسية. قد يختلف السعر النهائي حسب الطلبات الخاصة، التكاملات المخصصة، احتياجات التصميم الإضافية (رسوم، هوية بصرية، إلخ) أو توسيع نطاق المشروع."
    ),

