    "AGENT_LIST_ABOUT_TEXT" => array(
        "fr" => "Chaque agent est une brique métier autonome — messagerie, service client, marketing, finance, productivité ou données — entraînée sur vos process et déployée en moins de 72h. Pas de code à écrire, pas d'équipe technique à recruter&nbsp;: vous choisissez l'agent ci-dessous, on le connecte à vos outils, il travaille pour vous 24/7.",
        "en" => "Each agent is a self-contained business unit — messaging, customer service, marketing, finance, productivity or data — trained on your processes and deployed in under 72 hours. No code to write, no technical team to hire&nbsp;: you choose the agent below, we connect it to your tools, and it works for you 24/7.",
        "ar" => "كل وكيل هو وحدة عمل مستقلة — مراسلة، خدمة عملاء، تسويق، مالية، إنتاجية أو بيانات — مدرَّبة على مساراتكم الخاصة ومنشورة في أقل من 72 ساعة. بدون أي برمجة، وبدون الحاجة لتوظيف فريق تقني&nbsp;: تختارون الوكيل أدناه، نقوم بربطه بأدواتكم، ويعمل من أجلكم على مدار الساعة."
