    "FORML_WHY_DESC" => array(
        "fr" => "Hello World ne propose pas un simple catalogue de formations IA. Nous construisons une académie tournée vers trois grands leviers complémentaires : la croissance digitale, les systèmes intelligents et les médias de marque. Cette approche permet de relier acquisition, automatisation, développement et production de contenus dans une logique de performance réelle.",
        "en" => "Hello World doesn't offer a simple catalogue of AI training courses. We're building an academy built around three complementary growth levers: digital growth, intelligent systems and brand media. This approach connects acquisition, automation, development and content production in a real performance logic.",
        "ar" => "لا تقترح Hello World مجرد كتالوج تدريبات في الذكاء الاصطناعي. نحن نبني أكاديمية موجهة نحو ثلاث رافعات نمو متكاملة: النمو الرقمي، الأنظمة الذكية ووسائل الإعلام الخاصة بالعلامة. يربط هذا النهج بين الاستقطاب والأتمتة والتطوير وإنتاج المحتوى ضمن منطق أداء حقيقي."
    ),

