    "FORML_METHODE_DESC" => array(
        "fr" => "Nous ne formons pas à \"l'IA en général\". Nous partons de votre contexte, de vos objectifs et de vos contraintes métier. Notre pédagogie combine cadre stratégique, démonstrations concrètes, ateliers guidés et production de livrables utiles dès la formation.",
