        "ar" => "نحن لا ندرّب على \"الذكاء الاصطناعي بشكل عام\". ننطلق من سياقكم وأهدافكم وقيودكم المهنية. يجمع تعليمنا بين إطار استراتيجي وعروض توضيحية ملموسة وورشات موجهة وإنتاج مخرجات مفيدة منذ التدريب الأول."
