    "FORML_FAQ_A1" => array(
        "fr" => "Oui. Certaines formations accueillent des profils débutants ou intermédiaires, à condition que les objectifs soient clairs. Nous adaptons la profondeur selon le public. L'audit de maturité préalable nous permet de valider l'adéquation entre votre profil et le programme choisi.",
