        "ar" => "نعم. بعض التدريبات تستقبل مستويات مبتدئة أو متوسطة، شرط أن تكون الأهداف واضحة. نُكيّف العمق حسب الجمهور. يتيح لنا تدقيق النضج المسبق التحقق من توافق ملفكم الشخصي مع البرنامج المختار."
